-- Conversations and their membership.
-- IDs are UUIDs generated by the application (Hibernate), so the tables have no ID defaults.
--
-- Delete behavior: users referenced here can't be deleted (restrict). The application has no account
-- deletion yet; when it gets one, it has to decide what happens to the user's conversations instead of the
-- database silently removing them. Membership rows belong to their conversation and go with it (cascade).

create table conversations (
    id              uuid         primary key,
    type            varchar(16)  not null,
    -- Group conversations only. The application stores the name stripped of surrounding whitespace.
    name            varchar(100),
    created_by      uuid         not null references users (id) on delete restrict,
    -- Direct conversations only: the two participants, ordered so that direct_user1_id < direct_user2_id.
    -- With the order fixed, the unique constraint allows one direct conversation per pair of users, and
    -- concurrent requests for the same pair can't both insert one.
    direct_user1_id uuid         references users (id) on delete restrict,
    direct_user2_id uuid         references users (id) on delete restrict,
    created_at      timestamptz  not null,
    updated_at      timestamptz  not null,
    constraint conversations_type_valid check (type in ('DIRECT', 'GROUP')),
    -- Unique constraints treat NULLs as distinct, so group conversations (both columns NULL) never collide.
    constraint conversations_direct_pair_key unique (direct_user1_id, direct_user2_id),
    constraint conversations_direct_pair_ordered check (direct_user1_id < direct_user2_id),
    constraint conversations_direct_shape check (
        type <> 'DIRECT' or (name is null and direct_user1_id is not null and direct_user2_id is not null)),
    constraint conversations_group_shape check (
        type <> 'GROUP' or (name is not null and btrim(name) <> ''
                            and direct_user1_id is null and direct_user2_id is null)),
    constraint conversations_updated_after_created check (updated_at >= created_at)
);

create table conversation_members (
    id              uuid        primary key,
    conversation_id uuid        not null references conversations (id) on delete cascade,
    user_id         uuid        not null references users (id) on delete restrict,
    role            varchar(16) not null,
    joined_at       timestamptz not null,
    -- Also serves every lookup by conversation: its members, one member, member counts.
    constraint conversation_members_conversation_user_key unique (conversation_id, user_id),
    constraint conversation_members_role_valid check (role in ('ADMIN', 'MEMBER'))
);

-- Lists a user's conversations ("where user_id = ?", joined to conversations by conversation_id).
create index conversation_members_user_id_conversation_id_idx on conversation_members (user_id, conversation_id);
